:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #7a7a9a;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  border: 3px solid var(--accent);
  border-radius: 4px;
  box-shadow: 6px 6px 0 #000;
  padding: 24px;
  width: 100%;
  max-width: 440px;
}
h1 {
  margin: 0 0 16px;
  font-size: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}
.stats {
  display: flex;
  gap: 24px;
  margin-bottom: 16px;
  font-size: 16px;
  color: var(--muted);
}
.stats span { color: var(--text); font-weight: 700; }
.input-row { display: flex; gap: 8px; margin-bottom: 16px; }
input[type="text"] {
  flex: 1;
  padding: 10px 12px;
  font-size: 16px;
  background: var(--bg);
  border: 2px solid var(--muted);
  border-radius: 4px;
  color: var(--text);
}
input[type="text"]:focus {
  outline: none;
  border-color: var(--accent);
}
button {
  padding: 10px 16px;
  font-size: 16px;
  font-weight: 700;
  background: var(--accent);
  color: #fff;
  border: 2px solid #000;
  border-radius: 4px;
  cursor: pointer;
  box-shadow: 3px 3px 0 #000;
}
button:hover { filter: brightness(1.15); }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #000; }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
.todo-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.todo-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  background: var(--bg);
  border: 2px solid var(--muted);
  border-radius: 4px;
}
.todo-item.done .todo-text { text-decoration: line-through; color: var(--muted); }
.todo-text { flex: 1; word-break: break-word; }
.todo-item input[type="checkbox"] {
  width: 20px; height: 20px; accent-color: var(--accent); cursor: pointer;
}
.todo-item button {
  padding: 6px 10px;
  font-size: 14px;
  background: transparent;
  color: var(--accent);
  border-color: var(--accent);
  box-shadow: none;
}
.todo-item button:hover { background: var(--accent); color: #fff; }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const form = document.getElementById('todo-form');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let nextId = 1;
const tasks = [];

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function renderTask(task) {
  const li = document.createElement('li');
  li.className = 'todo-item';
  li.dataset.id = task.id;

  const cb = document.createElement('input');
  cb.type = 'checkbox';
  cb.id = `todo-check-${task.id}`;
  cb.checked = task.done;
  cb.setAttribute('aria-label', `Mark task ${task.id} complete`);

  const span = document.createElement('span');
  span.id = `todo-text-${task.id}`;
  span.className = 'todo-text';
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.id = `todo-delete-${task.id}`;
  del.textContent = 'Delete';
  del.setAttribute('aria-label', `Delete task ${task.id}`);

  if (task.done) li.classList.add('done');

  cb.addEventListener('change', () => {
    task.done = cb.checked;
    li.classList.toggle('done', task.done);
    updateCounts();
  });

  del.addEventListener('click', () => {
    const idx = tasks.indexOf(task);
    if (idx !== -1) tasks.splice(idx, 1);
    li.remove();
    updateCounts();
  });

  li.append(cb, span, del);
  list.appendChild(li);
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  renderTask(task);
  input.value = '';
  input.focus();
  updateCounts();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  addTask();
});

addBtn.addEventListener('click', (e) => {
  e.preventDefault();
  addTask();
});

updateCounts();
